#!/usr/bin/env python3
"""Generate supabase/migrations/0007_content.sql: real season 26/27 content for LL Dance Studio from site/*.json and the
team calendar PDFs on lldancestudio.dk – team descriptions/prices/covers, trainers, weekly trainings (Nov 2026 – Jun 2027,
holidays skipped), training camps, the season's events (Julebal, Rangliste, DM, Show IT, Afdansningsbal …) and the shop.
Idempotent: re-running updates teams/products and only inserts what is missing. Run: python3 scripts/gen-content-sql.py
"""
import json, os, re, html
from datetime import date, timedelta, datetime

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SCHED = json.load(open(os.path.join(ROOT, "site", "schedule.json")))
TEAMS = {t["slug"].strip("/"): t for t in json.load(open(os.path.join(ROOT, "site", "teams.json")))}
P = json.load(open(os.path.join(ROOT, "site", "pages.json")))
U = html.unescape
def q(s): return "NULL" if s is None else "'" + str(s).replace("'", "''") + "'"
def arr(xs): return "array[" + ",".join(q(x) for x in xs) + "]::text[]" if xs else "'{}'::text[]"

# website slug -> team name in the DB seed (supabase/seed.sql)
SLUG2NAME = {"mini-cuties": "Mini Cuties", "hip-hop-mini-born-2": "Hip Hop Mini", "shining-stars": "Shining Stars",
  "contemporary-born-juniorbegynderovet": "Contemporary Begynder", "contemporary-bornjuniorvoksen-ovet-og-elite": "Contemporary Elite",
  "hip-hop-junior-amp-voksen-ovet-elite": "Hip Hop Junior & Voksen Elite", "spring-og-tumbling-born": "Spring & Tumbling Børn",
  "hip-hop-junior-voksen-begynder-ovet": "Hip Hop Junior & Voksen Begynder", "control": "Control", "mini-angels-25-26": "Mini Angels",
  "the-axis-25-26": "The AXIS", "styrke-traening-junior-voksen": "Styrketræning Junior & Voksen", "the-attitude-25-26-2": "Apexion",
  "disco-begynder": "Disco Dance", "satellite-stars": "Satellite Stars", "new-age-25-26-2": "New Age", "danse-stjerner-2": "Mini Stjernetrin",
  "disco-konkurrence-2": "Disco", "disco-slow": "Disco Slow", "the-attitude-25-26": "Airy", "sky-stars": "Sky Stars",
  "styrke-traening-born": "Styrketræning Børn", "empire": "Empire", "mini-glitters-2": "Mini Magic", "spring-og-tumbling-mini-born": "Spring & Tumbling Mini",
  "contemporary-born-junior-voksen-ovet-og-elite-26-27": "Smidighed & Acro", "spring-og-tumbling-junior-voksen": "Spring & Tumbling Junior & Voksen",
  "danse-stjerner": "Danse Stjerner", "ballet-mini-born": "Ballet Mini", "no-addiction": "No Addiction"}
HITFIT = {1: "Hit Fit Dance tirsdag", 2: "Hit Fit Dance onsdag"}
TEKNIK = {"New Age": "Teknik New Age", "Satellite Stars & Sky Stars": "Teknik Børn Showdance", "The AXIS": "Teknik The AXIS",
          "Empire & Control": "Teknik Empire & Control", "Apexion & Airy": "Teknik Apexion & Airy", "Mini Angels": "Teknik Mini"}
ARCHIVE = ["Division", "Hip Hop Børn", "Ballet"]   # not in the 26/27 plan
# trainer name as written on team pages -> staff name (pages.json)
ALIAS = {"Mille Grøn": "Mille Grøn Madsen", "Line Lund": "Line Lund Olesen", "Seline Jepsen": "Seline Glerup Jepsen",
         "Annemette Kjær": "Annemette Lund Kjær", "Chirstine Lassen": "Christine Lassen"}
STAFF = [s["name"] for s in P["staff"]]
def trainers(txt):
    if not txt: return []
    txt = re.sub(r"Hold \d:\s*", "", txt); out = []
    for n in re.split(r"\s*(?:&|·|,| og )\s*", txt):
        n = ALIAS.get(n.strip(), n.strip())
        if n in STAFF: out.append(n)
    return out
def team_trainers(slug):
    f = TEAMS.get(slug, {}).get("facts") or {}; return trainers(f.get("trainer")), trainers(f.get("assistant"))

out = ["-- 0007_content.sql – generated by scripts/gen-content-sql.py (season 26/27 content from lldancestudio.dk). Idempotent.",
       "alter table team add column if not exists cover_url text;   -- external cover (website photo) until a real cover_path is uploaded",
       "alter table team add column if not exists price text;",
       "alter table team add column if not exists years text;",
       "alter table team add column if not exists day_time text;",
       "do $$ declare sid uuid := (select id from school where slug = 'llds'); r_store uuid; r_lille uuid; t uuid; p uuid; tr uuid; rule uuid; d date; begin",
       "select id into r_store from room where school_id = sid and name = 'Store Sal'; select id into r_lille from room where school_id = sid and name = 'Lille Sal';"]

# ---- teams
for slug, name in SLUG2NAME.items():
    t = TEAMS[slug]; f = t["facts"]
    desc = (t.get("intro") or "") ; secs = [s for s in t.get("sections", []) if s.get("body") and not any(k in s["title"].lower() for k in ("tilmeldingsprisen", "rater", "familierabat", "kontakt os", "prøvetimer", "forældre-dage")) and s["body"][:60] not in desc]
    if secs: desc += "\n\n" + "\n\n".join(f"{U(s['title'])}\n{U(s['body'])}" for s in secs[:3])
    cover = (t.get("images") or [None])[0]
    out.append(f"update team set description = {q(desc.strip())}, price = {q(f.get('price'))}, years = {q(f.get('years'))}, day_time = {q(f.get('day_time'))}, closed = {str(bool(f.get('closed'))).lower()}, cover_url = coalesce(cover_url, {q(cover)}) where school_id = sid and name = {q(name)};")
for n in ARCHIVE: out.append(f"update team set archived = true where school_id = sid and name = {q(n)};")
out.append(f"update team set day_time = 'Tirsdag kl. 19:25–20:10', price = '10 klip = 625 kr. (klippekort)' where school_id = sid and name = 'Hit Fit Dance tirsdag';")
out.append(f"update team set day_time = 'Onsdag kl. 20:20–21:05', price = '10 klip = 625 kr. (klippekort)' where school_id = sid and name = 'Hit Fit Dance onsdag';")

# ---- staff persons
for s in P["staff"]:
    first, last = s["name"].split(" ", 1)
    out.append(f"insert into person(school_id, first_name, last_name, status, wished_roles) select sid, {q(first)}, {q(last)}, 'approved', '{{trainer}}' where not exists (select 1 from person where school_id = sid and first_name = {q(first)} and last_name = {q(last)});")
def person_sel(name):
    first, last = name.split(" ", 1); return f"(select id from person where school_id = sid and first_name = {q(first)} and last_name = {q(last)} limit 1)"
def member(name, team, role):
    out.append(f"insert into membership(person_id, team_id, role) select {person_sel(name)}, (select id from team where school_id = sid and name = {q(team)}), '{role}' on conflict do nothing;")
for slug, name in SLUG2NAME.items():
    trs, ass = team_trainers(slug)
    for n in trs: member(n, name, "trainer")
    for n in ass: member(n, name, "assistant")
member("Annemette Lund Kjær", "Hit Fit Dance tirsdag", "trainer"); member("Line Lund Olesen", "Hit Fit Dance onsdag", "trainer")
for tk in TEKNIK.values(): member("Line Lund Olesen", tk, "trainer")

# ---- weekly trainings 2 Nov 2026 – 3 Jun 2027 (last teaching week = week 22), holidays skipped (assumed; Line can delete)
HOL = [(date(2026,12,19), date(2027,1,3)), (date(2027,2,15), date(2027,2,21)), (date(2027,3,22), date(2027,3,29)), (date(2027,5,6), date(2027,5,7)), (date(2027,5,17), date(2027,5,17))]
def holiday(d): return any(a <= d <= b for a, b in HOL)
START, END = date(2026, 11, 2), date(2027, 6, 3)
out.append("-- weekly trainings (session.weekly_rule_id groups each class so 'this and future' edits work)")
for c in SCHED["classes"]:
    if "Hit Fit" in c["name"]: tname = HITFIT[c["day"]]
    elif c.get("slug"): tname = SLUG2NAME[c["slug"]]
    else: tname = TEKNIK[c["note"].split("på ")[-1]]
    h1, h2 = c["time"].replace("–", "-").split("-"); room = "r_store" if c["room"] == "Store Sal" else "r_lille"
    out.append(f"select id into t from team where school_id = sid and name = {q(tname)}; select person_id into tr from membership where team_id = t and role = 'trainer' limit 1; rule := gen_random_uuid();")
    dates = [START + timedelta(days=i) for i in range((END - START).days + 1) if (START + timedelta(days=i)).weekday() == c["day"] and not holiday(START + timedelta(days=i))]
    vals = ",".join(f"('{d}T{h1}','{d}T{h2}')" for d in dates)
    out.append(f"insert into session(school_id, team_id, room_id, starts_at, ends_at, trainer_id, weekly_rule_id) select sid, t, {room}, (v.s::timestamp) at time zone 'Europe/Copenhagen', (v.e::timestamp) at time zone 'Europe/Copenhagen', tr, rule from (values {vals}) as v(s, e) where not exists (select 1 from session x where x.team_id = t and x.starts_at = (v.s::timestamp) at time zone 'Europe/Copenhagen');")

# ---- training camps / extra trainings from the calendar PDFs (team-specific)
CAMPS = [("Empire", "2026-12-05", "10:00", "13:00", "Store"), ("Empire", "2027-01-16", "10:00", "13:00", "Store"), ("Empire", "2027-04-03", "12:00", "15:00", "Store"),
  ("Mini Cuties", "2026-12-12", "10:00", "12:00", "Store"), ("Mini Cuties", "2027-05-08", "10:00", "12:00", "Store"),
  ("Control", "2026-11-27", "16:00", "20:00", "Store"), ("Control", "2027-01-16", "16:00", "20:00", "Store"), ("Control", "2027-04-04", "16:00", "20:00", "Store"),
  ("Sky Stars", "2026-11-15", "08:00", "12:00", "Store"), ("Sky Stars", "2027-02-06", "08:00", "12:00", "Store"), ("Sky Stars", "2027-05-07", "12:00", "16:00", "Store"),
  ("Satellite Stars", "2027-01-17", "15:30", "18:30", "Lille"), ("Satellite Stars", "2027-04-04", "13:00", "16:00", "Lille"),
  ("Shining Stars", "2026-12-05", "08:00", "10:00", "Store"), ("Shining Stars", "2027-01-16", "08:00", "10:00", "Store"),
  ("Mini Magic", "2026-11-28", "10:00", "12:00", "Store"), ("Mini Magic", "2027-04-04", "10:00", "12:00", "Store"),
  ("No Addiction", "2026-11-14", "10:00", "12:00", "Store"), ("No Addiction", "2026-12-06", "08:00", "12:00", "Store"), ("No Addiction", "2027-01-17", "08:00", "12:00", "Store"),
  ("No Addiction", "2027-02-07", "08:00", "12:00", "Store"), ("No Addiction", "2027-04-02", "17:00", "19:00", "Store"), ("No Addiction", "2027-05-09", "16:00", "20:00", "Store")]
out.append("-- training camps (træningslejr) from the team calendars")
for tn, d, a, b, room in CAMPS:
    out.append(f"select id into t from team where school_id = sid and name = {q(tn)}; select person_id into tr from membership where team_id = t and role = 'trainer' limit 1;")
    out.append(f"insert into session(school_id, team_id, room_id, title, starts_at, ends_at, trainer_id) select sid, t, {'r_store' if room == 'Store' else 'r_lille'}, 'Træningslejr', '{d}T{a}'::timestamp at time zone 'Europe/Copenhagen', '{d}T{b}'::timestamp at time zone 'Europe/Copenhagen', tr where not exists (select 1 from session x where x.team_id = t and x.starts_at = '{d}T{a}'::timestamp at time zone 'Europe/Copenhagen');")

# ---- events (season calendar; all public on the website)
SHOW_TEAMS = ["Mini Angels", "Satellite Stars", "Sky Stars", "New Age", "Control", "Empire", "The AXIS", "Apexion", "Airy", "No Addiction"]
JR_ADULT = ["Control", "Empire", "The AXIS", "Apexion", "Airy", "No Addiction"]; MINI_KIDS = ["Mini Angels", "Satellite Stars", "Sky Stars", "New Age"]
SHOWIT = ["Mini Cuties", "Shining Stars", "Mini Magic", "Mini Angels", "Satellite Stars", "Sky Stars", "Empire", "Control"]
EVENTS = [
  ("Julebal", "social", "2026-12-19T11:00", "2026-12-19T15:00", "Ulstrup Hallen", [], "Julebal for alle hold – opvisning, hygge og julestemning. Familie og venner er velkomne.", None),
  ("KC Rangliste 1 – Junior & Voksen", "competition", "2027-01-30T08:00", "2027-01-30T18:00", "Forum Horsens", JR_ADULT, "1. ranglistestævne (Konkurrence Center): Junior 1, Junior 2, Voksen 1 & 2. Hele dagen.", "2027-01-15"),
  ("KC Rangliste 1 – Mini Børn & Børn", "competition", "2027-01-31T08:00", "2027-01-31T18:00", "Forum Horsens", MINI_KIDS, "1. ranglistestævne: Mini Børn, Børn 1 & Børn 2. Hele dagen.", "2027-01-15"),
  ("KC Rangliste 2 – Børn 2, Junior 2 & Voksen", "competition", "2027-02-27T08:00", "2027-02-27T18:00", "Forum Horsens", ["New Age", "The AXIS", "Apexion", "Airy", "No Addiction"], "2. ranglistestævne. Hele dagen.", "2027-02-12"),
  ("KC Rangliste 2 – Mini Børn, Børn 1 & Junior 1", "competition", "2027-02-28T08:00", "2027-02-28T18:00", "Forum Horsens", ["Mini Angels", "Satellite Stars", "Sky Stars", "Control", "Empire"], "2. ranglistestævne. Hele dagen.", "2027-02-12"),
  ("Danmark Danser – Solo & Duo", "competition", "2027-03-06T08:00", "2027-03-07T18:00", "Esbjerg Musikhus", [], "Solo- og duo-konkurrence over to dage.", "2027-02-19"),
  ("CPH Open", "competition", "2027-03-13T08:00", "2027-03-13T18:00", "Idrætscenter Midtfyn", ["The AXIS", "Apexion", "Airy", "New Age", "No Addiction"], "Elitehold samt solo & duo.", "2027-02-26"),
  ("KC Semifinale", "competition", "2027-04-10T08:00", "2027-04-10T18:00", "Forum Horsens", SHOW_TEAMS, "Semifinale for de hold, der er gået videre fra ranglisten.", "2027-03-26"),
  ("CPH Open Finale", "competition", "2027-04-17T08:00", "2027-04-17T18:00", "Idrætscenter Midtfyn", ["The AXIS", "Apexion", "Airy", "New Age", "No Addiction"], "Finale for kvalificerede elitehold samt solo & duo.", "2027-04-02"),
  ("KC Finale", "competition", "2027-05-15T08:00", "2027-05-15T18:00", "ODEON, Odense", SHOW_TEAMS, "Finalen for de hold, der nåede finalen.", "2027-04-30"),
  ("DM Showdance – Børn, Junior & Voksen", "competition", "2027-05-22T08:00", "2027-05-22T19:00", "Aalborg Kongres & Kulturcenter", JR_ADULT + ["New Age", "Satellite Stars", "Sky Stars"], "Danmarksmesterskab: Børn, Junior og Voksen konkurrence samt Junior og Voksen Talent.", "2027-05-07"),
  ("DM Showdance – Mini Børn Debutant & Talent", "competition", "2027-05-23T08:00", "2027-05-23T19:00", "Aalborg Kongres & Kulturcenter", ["Mini Angels", "Mini Magic", "Shining Stars", "Mini Cuties", "Satellite Stars", "Sky Stars", "Empire"], "Danmarksmesterskab: Minibørn og Børn Debutant/Talent samt Junior Debutant.", "2027-05-07"),
  ("Show IT", "show", "2027-05-29T09:00", "2027-05-29T18:00", "Spektrum Vejle", SHOWIT, "Show for Begynder, Øvet og Øvet+ samt Solo & Duo. Hele dagen.", "2027-05-14"),
  ("Afdansningsbal", "social", "2027-06-05T11:00", "2027-06-05T15:00", "Ulstrup Hallen", [], "Sæsonens afslutning for alle hold – opvisning, pokaler og tak for i år.", None),
  ("Danmark Danser – Finale (Solo & Duo)", "competition", "2027-06-06T08:00", "2027-06-06T18:00", "Det Kongelige Teater", [], "Finalen i Danmark Danser for solo & duo.", None),
]
out.append("-- events")
for title, kind, s, e, place, teams, info, dl in EVENTS:
    tids = f"array(select id from team where school_id = sid and name = any({arr(teams)}))" if teams else "'{}'::uuid[]"
    out.append(f"insert into event(school_id, title, kind, starts_at, ends_at, place, team_ids, info, signup_deadline, visibility) select sid, {q(title)}, '{kind}', '{s}'::timestamp at time zone 'Europe/Copenhagen', '{e}'::timestamp at time zone 'Europe/Copenhagen', {q(place)}, {tids}, {q(info)}, {q(dl)}, 'public' where not exists (select 1 from event x where x.school_id = sid and x.title = {q(title)});")

# ---- shop
ORDER = ["XXS", "XS", "S", "M", "L", "XL", "XXL"]
def sizes(sz):
    chips = []
    for part in re.split(r",\s*", sz):
        p = part.strip(); m = re.match(r"^(?:Børn |voksen )?([X]*[SML]|XL|XXL|XXS|XS)–(X*[SML]|XL|XXL)$", p, re.I)
        if m: a, b = m.group(1).upper(), m.group(2).upper(); chips += ORDER[ORDER.index(a):ORDER.index(b) + 1]; continue
        m = re.match(r"^Børn (\d+)–(\d+)$", p)
        if m: chips += [str(x) for x in range(int(m.group(1)), int(m.group(2)) + 1, 10)]; continue
        if p.lower() == "one size": continue
        chips.append(p)
    return chips
out.append("-- shop (Stjerneshoppen)")
for n, price, sz in P["shop"]["products"]:
    out.append(f"insert into product(school_id, name, price_dkk, sizes, visibility, active) select sid, {q(U(n))}, {price}, {arr(sizes(sz))}, 'public', true where not exists (select 1 from product x where x.school_id = sid and x.name = {q(U(n))});")
    out.append(f"update product set price_dkk = {price}, sizes = {arr(sizes(sz))} where school_id = sid and name = {q(U(n))};")
out.append("end $$;")
open(os.path.join(ROOT, "supabase", "migrations", "0007_content.sql"), "w").write("\n".join(out) + "\n")
print("wrote 0007_content.sql:", len(out), "statements")
